import{_ as e,o as a,c as t,ag as _}from"./chunks/framework.Ddwm6YJC.js";const m=JSON.parse('{"title":"第07章 汽水","description":"","frontmatter":{},"headers":[],"relativePath":"第07章_汽水.md","filePath":"第07章_汽水.md"}'),r={name:"第07章_汽水.md"};function o(n,p,s,c,i,d){return a(),t("div",null,[...p[0]||(p[0]=[_('<h1 id="第07章-汽水" tabindex="-1">第07章 汽水 <a class="header-anchor" href="#第07章-汽水" aria-label="Permalink to &quot;第07章 汽水&quot;">​</a></h1><p>初三夏的晚自习，风是烫的。</p><p>电扇在头顶转，发出很旧的嗡鸣，空气里有粉笔灰，有汗味，还有后排传来的薄荷油气息。我一坐下，就看见桌肚里多了一瓶东西。</p><p>橘子汽水。</p><p>玻璃瓶，冰凉，瓶壁上还挂着水珠，贴着我的习题册，洇湿了一小块纸角。阳光，不对，灯光照上去，里面的气泡一个劲往上顶，细小，着急，像夏天的蝉声被装进了水里。</p><p>我愣住了。</p><p>我的桌子在靠窗那排，风一吹，窗帘会扫到手背。周围的人都在低头写字，顾远在啃笔，何晓在传小纸条给林小满，谁也没有往我这边看。江苒坐在斜前方，背挺得很直，马尾用皮筋扎着，钥匙扣挂在书包侧面，小铃铛偶尔轻轻响一声。</p><p>像是怕被谁发现，我把那瓶汽水往桌肚里又推了推。</p><p>自习安静得能听见纸页翻动的声音。我盯着那瓶汽水看了很久，手指碰到瓶身，凉意一下窜到手心，很舒服。瓶盖底下压着一张很小的纸，折成小方块。</p><p>我把纸拿出来，展开。</p><p>上面是很圆的字：“天太热，请你喝。”</p><p>没有落款。</p><p>可我知道是谁。字迹我认得，江苒的字总是圆圆的，转弯的地方很用力，像她说话的样子，明亮，干脆。</p><p>心跳忽然快了起来。</p><p>我想起初一秋她递给我的枇杷，想起初二春走廊里她钥匙上的铃铛声。这些记忆在夏天蒸腾的空气里变得很清晰，带着甜味。</p><p>下课铃响的时候，教室一下活了。有人去接水，有人跑去走廊透气。江苒和林小满一起走出去，路过我身边时，她没有停，也没有看我，只是钥匙上的小铃铛叮地响了一下，清脆，短促。</p><p>我握着那瓶汽水，手心全是水。</p><p>喝，还是不喝。</p><p>薄荷水的凉还在记忆里，那是我给她的。这一次，是她给我的橘子汽水。我想了很久，把汽水打开，喝了一小口。</p><p>很甜，橘子味很浓，气泡在舌头上炸开，有点刺，又有点让人想笑。后味是凉的，从喉咙一直凉到胃里，晚自习的燥热被压下去一半。</p><p>我看着瓶子，忽然觉得不能白喝。</p><p>第二天，我早到了一会儿。</p><p>雾山的夏天亮得早，校门口的雾已经散了，宋阿婆的小推车支在老位置，上面摆着牛奶，包子，还有几瓶汽水。她的头发全白了，笑起来眼角全是褶，认得我们这些总在她那里买早饭的学生。</p><p>“阿聿，今儿要啥？”她问我。</p><p>我要了一盒牛奶，还是温的，纸盒外壁有点潮。我把牛奶抱在怀里，一路抱到教室，趁着没人，把它塞进江苒的桌肚。</p><p>我也学她，写了一张小纸条。</p><p>我想了很久才下笔。我的字很瘦，写得很慢，怕写错。我写的是：“谢谢，很好喝。”</p><p>把纸条压在牛奶底下时，我的手在抖。</p><p>那天一整天，我都不敢看她。</p><p>上课时，叶老师在黑板上写题，粉笔吱吱响。我盯着黑板，余光却总往斜前方飘。江苒很安静，认真记笔记，笔尖划过纸面，沙沙的。中午她去食堂，回来时桌上的牛奶已经不见了，纸条也不见了。</p><p>我心里空了一下，又满了一下。</p><p>下午的自习，她经过我身边去交作业，本子放在我桌上时，指尖轻轻碰了一下我的桌面，很轻，像蜻蜓点水。她的钥匙铃铛跟着晃，发出细碎的声音。</p><p>我低着头，耳朵发烫。</p><p>放学时，宋阿婆叫住我。</p><p>“阿聿，你今早买的牛奶，是给那个笑起来很亮的姑娘吧？”她眯着眼笑，声音很低，带着雾山老人特有的软。</p><p>我脸一下红了，点点头，又摇摇头，不知道该说什么。</p><p>宋阿婆把一瓶橘子汽水递给我，瓶身还滴着水：“她下午来我这儿，问我你早上买了啥。我可没多嘴。”</p><p>我接过汽水，冰得指尖发麻。</p><p>原来，这场交换，被她看见了。</p><p>从那天起，桌肚里的游戏开始了。</p><p>隔一天，我的桌肚里会出现一瓶橘子汽水，有时还带着宋阿婆推车上的凉气，瓶底有一点碎冰似的光。隔一天，她的桌肚里会出现一盒牛奶，有时是温的，有时是凉的，底下压着我的纸条。</p><p>纸条都很短。</p><p>她写：“今天背书顺利吗。”</p><p>我回：“顺利，谢谢。”</p><p>她写：“电扇对着吹，脖子疼。”</p><p>我回：“我带了薄荷油，明天给你。”</p><p>我们谁也没有明说，可全班似乎都知道了。顾远有一次撞见我往她桌肚里塞牛奶，挤眉弄眼，压着嗓子笑：“沈聿，你可以啊。”我推他一把，让他小声点。他还是笑，笑声里没有恶意。</p><p>何晓和林小满更直接，有一次晚自习前，林小满回头看我，眼睛弯弯的：“沈聿，橘子汽水好喝吗。”我还没回答，江苒就伸手去捂她的嘴，两个女孩笑成一团，铃铛声混在笑声里，叮叮当当。</p><p>我也笑了。</p><p>初三夏的热是很具体的。蝉鸣从早叫到晚，午后最盛，一阵一阵，像潮水。教室的墙被晒得发烫，摸一下，手心会出汗。墨水写到一半会洇开，纸面软软的。可因为那瓶汽水，热里有了盼头。</p><p>每天早上一进教室，我都会先看一眼桌肚。看到玻璃瓶的影子，心就会定下来。看不到，心就会悬着，上课也忍不住往门口看。</p><p>江苒也是吗。我不敢问。</p><p>我只知道，她喝牛奶的样子被林小满描述过。林小满说，江苒每次拿到牛奶，都会先把纸条看两遍，再把纸条折起来，放进铅笔盒最里层。铅笔盒里，已经攒了好几张我写的纸条，边角都压得很平。</p><p>听到这话时，我正在喝汽水，差点呛到。气泡顶着喉咙，又酸又甜。</p><p>有一天晚自习停电。</p><p>电扇停了，灯灭了，教室里一阵骚动，很快又安静下来。有人打开窗，夏夜的风涌进来，带着外面香樟树的味道，还有远处操场的蛙鸣。叶老师让大家先趴着休息，不许大声说话。</p><p>黑暗里，什么都看不清，只听见呼吸声，纸张被风吹动的声音，还有钥匙铃铛偶尔的轻响。</p><p>那铃声离我很近。</p><p>江苒不知什么时候走到了我旁边，站在过道里，声音很轻：“沈聿，你桌上有汽水吗。”</p><p>那是我第一次在黑暗里听她叫我的名字。清晰，温热。</p><p>我说：“有，还凉着，你喝吗。”</p><p>她笑了一下，我听得出来，气息轻轻的：“那是给你的。我就是问问，怕你没看到。”</p><p>风吹过来，她的发梢扫到我的手背，有点痒。</p><p>我的心跳得很快，大声到我怕她听见。我把那瓶汽水塞到她手里，瓶身相触，凉意在我们之间传了一下。</p><p>“一起喝吧。”我说。</p><p>她没有拒绝。</p><p>黑暗里，我们轮流喝那瓶橘子汽水。玻璃瓶口有点凉，汽水已经不太冰了，可气泡还在，喝下去，舌尖微微发麻。谁也没有说话，只有蝉声，风声，还有瓶子递来递去时轻微的磕碰声。</p><p>那一刻，我忽然觉得，纸条写得再多，也比不上这样靠近的一分钟。</p><p>来电的时候，灯光唰地亮起，所有人都眯起眼。江苒已经回到座位上，低着头，耳朵红红的，手里捏着空的玻璃瓶。林小满凑过去看她，两人说了什么，江苒轻轻推了她一下。</p><p>我看着空了的桌肚，心里却满得要溢出来。</p><p>这样的交换，持续了两周。</p><p>宋阿婆全看在眼里。每天早上，她都会给我留一盒最新到的牛奶，每天傍晚，她都会给江苒留一瓶最冰的橘子汽水。她不多问，只是笑，笑纹里藏着夏天的光。有一次她对我说：“你们这样的来来去去，阿婆年轻时也见过。”</p><p>我问：“后来呢。”</p><p>她摆摆手，推着车往雾里走：“后来啊，总要有人先开口。”</p><p>这句话，在我心里落了很久。</p><p>晚自习结束，教室空了。我收拾书包，看到桌肚里又多了一瓶橘子汽水。今天的纸条比平时长一点：“明天是最后一次自习了，你会来吗。”</p><p>窗外蝉鸣正盛，夜风带着白天的余热，吹动窗帘。江苒的座位已经空了，可她的钥匙铃铛声似乎还留在空气里，没有散。</p><p>我把纸条折好，放进口袋最贴身的地方。牛奶已经准备好了，就在书包侧面，温的。</p><p>明天，谁先开口。</p>',79)])])}const f=e(r,[["render",o]]);export{m as __pageData,f as default};
